from gklib import L, S, Q
L("world","continents-and-oceans","5-7","Seven Continents and Five Oceans","Learn the big pieces of land and water that make up our world.","🌍",[
 S("The seven continents","A continent is a very large piece of land. | The seven continents are Asia, Africa, North America, South America, Antarctica, Europe and Australia. | Asia is the biggest continent, and India is in Asia.",["Seven continents","Asia is the biggest","India is in Asia"]),
 S("The five oceans","Oceans are huge areas of salty water. | The five oceans are the Pacific, Atlantic, Indian, Southern and Arctic. | The Pacific Ocean is the biggest and the deepest of all.",["Five oceans","Pacific is the biggest"]),
 S("Close to home","The Indian Ocean touches the south of India. | The Bay of Bengal is on the east side and the Arabian Sea is on the west side. | Chennai is on the coast of the Bay of Bengal.",["Indian Ocean in the south","Bay of Bengal in the east","Arabian Sea in the west"]),
 S("Find them on a globe","A globe is a small model of the Earth. | Blue on a globe or map usually shows water and the other colours show land. | Try spinning a globe and finding all seven continents.",["A globe is a model of Earth","Blue is water"]),
],facts=["Antarctica is the coldest continent and has no permanent human residents, only scientists who visit.","About 71 percent of Earth is covered by water.","Australia is both a country and a continent."],
quiz=[Q("Which is the biggest continent?",["Africa","Asia","Europe"],1,"Asia is the biggest."),
Q("How many oceans are there?",["Three","Five","Seven"],1,"There are five oceans."),
Q("Chennai is on the coast of which bay?",["Bay of Bengal","Arabian Sea","Gulf of Mannar"],0,"Chennai lies on the Bay of Bengal.")],tags=["continents","oceans","maps"])

L("world","how-to-read-a-map","8-10","How to Read a Map","Directions, scale, legends and grid lines: the four tools that unlock any map.","🧭",[
 S("Directions","The four main directions are north, east, south and west. | Between them are north-east, south-east, south-west and north-west. | A compass has a magnetic needle that points north, and many maps have a small compass rose to show directions.",["N, E, S, W","Compass points north","Maps show a compass rose"]),
 S("Scale","A map is a small picture of a big place. | The scale tells how much smaller it is, for example 1 centimetre on the map stands for 10 kilometres on the ground. | Use a ruler and the scale to find real distances.",["Scale links map to the ground","Measure with a ruler"]),
 S("Legend","A map uses signs and colours instead of words. | The legend or key explains them: blue for water, green for forests and a small symbol for a railway or a temple. | Always check the legend first.",["Symbols and colours","Legend explains them"]),
 S("Latitude and longitude","Imaginary lines called latitudes run east to west, and longitudes run north to south. | The equator is the 0 degree latitude line. | Every place on Earth can be named by its latitude and longitude, like an address for the whole planet.",["Latitude: east-west lines","Longitude: north-south lines","Equator: 0 degrees"]),
],facts=["The Prime Meridian, the 0 degree longitude line, passes through Greenwich in London.","Chennai is at about 13 degrees north and 80 degrees east.","The Tropic of Cancer passes through India."],
quiz=[Q("What does a map's legend show?",["Distance","Meaning of its symbols","The date"],1,"The legend explains the signs and colours."),
Q("Which line is at 0 degrees latitude?",["Equator","Prime Meridian","Tropic of Cancer"],0,"The equator is 0 degrees latitude."),
Q("What does a map scale tell you?",["How the map is coloured","How much smaller the map is than the real place","Who made it"],1,"It tells how distances on the map compare with real distances.")],tags=["maps","latitude","compass"])

L("world","countries-and-cultures-around-the-world","8-10","Countries and Cultures Around the World","Fun facts about people, foods, festivals and greetings across the world.","🎎",[
 S("Different places, different ways","There are around two hundred countries in the world. | People in each country have their own languages, clothes, foods and festivals. | Learning about them helps us understand and respect each other.",["About 200 countries","Many cultures"]),
 S("Greetings","In India we say namaste or vanakkam with folded hands. | In Japan people often bow. | In many countries people shake hands, and in New Zealand the Maori people greet by touching noses in a greeting called the hongi.",["Namaste or vanakkam","Bow in Japan","Hongi in New Zealand"]),
 S("Food and festivals","Rice is the main food for billions of people in Asia. | Italy is known for pasta, Mexico for tortillas and India for its many curries, idlis and dosas. | Festivals like Pongal, Diwali, Eid, Christmas and the Chinese New Year bring families together.",["Different staple foods","Many festivals"]),
 S("What we share","Everywhere people love music, games, stories and their families. | Kindness is understood in every language. | The more we learn, the more we see how alike we are.",["We share many things"]),
],facts=["Papua New Guinea has more than eight hundred languages, the most of any country.","Tamil is one of the oldest living languages in the world.","In Japan, taking off shoes before entering a home is the custom, just as in many Indian homes."],
quiz=[Q("In Japan, what is a common greeting?",["Bowing","Hugging every person","Waving a flag"],0,"People often greet with a bow in Japan."),
Q("Which language is one of the oldest living languages?",["Tamil","Binary","Morse code"],0,"Tamil has a very long recorded history and is still spoken today."),
Q("Why learn about other cultures?",["To understand and respect others","To argue","To win"],0,"Understanding helps us live together kindly.")],tags=["culture","countries"])

L("science","light-and-colour","8-10","Light and Colour","How light travels in straight lines, how a prism splits white light and why the sky is blue.","🌈",[
 S("Light travels in straight lines","Light moves in straight lines, which is why shadows have clear shapes. | It is the fastest thing in the universe, about three hundred thousand kilometres every second. | Light from the Sun takes about eight minutes to reach Earth.",["Straight lines","Very fast","Sun to Earth: about 8 minutes"]),
 S("A rainbow in a prism","White light is a mix of all the colours. | When it passes through a glass prism or raindrops, each colour bends by a different amount and spreads out. | The colours always appear in the same order: violet, indigo, blue, green, yellow, orange, red.",["White light is a mix","Prism splits it","VIBGYOR order"],"rainbow-prism"),
 S("Why things have colour","A red apple looks red because it reflects red light and soaks up the other colours. | A white paper reflects almost all colours, and a black cloth absorbs most of them. | That is why a black shirt feels hotter in the Sun.",["Objects reflect some colours","Black absorbs most light"]),
 S("Blue sky, red sunset","Air spreads the blue part of sunlight in all directions more than the red part, so the sky looks blue. | At sunset the light travels through more air, the blue is scattered away, and the red and orange remain. | A rainbow needs sunshine behind you and rain in front of you.",["Blue light is scattered most","Sunset light is red"]),
],facts=["There is no sound in space, but light travels through the emptiness of space.","The moon shines only by reflected sunlight.","Some animals, such as bees, can see ultraviolet light that humans cannot see."],
quiz=[Q("Which colour is at one end of the rainbow?",["Red","Pink","Black"],0,"Red is at the outer edge and violet at the inner edge."),
Q("Why does a red apple look red?",["It reflects red light","It makes red light","It absorbs red light"],0,"It reflects red light and absorbs most other colours."),
Q("About how long does sunlight take to reach Earth?",["8 seconds","8 minutes","8 hours"],1,"Sunlight takes about 8 minutes.")],tags=["light","rainbow","colour"])

L("science","sound-how-we-hear","8-10","Sound: How We Hear","Vibrations, waves, pitch and loudness, and why there is no sound in space.","🔊",[
 S("Sound is a vibration","Every sound starts with something vibrating, which means moving back and forth very fast. | A drum skin, a guitar string and your own throat all vibrate when they make sound. | Touch your throat while humming and you can feel it.",["Sound = vibration","Feel it in your throat"],"sound-waves"),
 S("Sound waves","The vibrating object pushes the air around it, and the push travels as a wave. | Sound needs something to travel through, such as air, water or a solid. | In empty space there is nothing to carry it, so space is silent.",["Waves travel through matter","No sound in space"],"sound-waves"),
 S("Pitch and loudness","Pitch is how high or low a sound is, and it depends on how fast the vibration is. | A small bell vibrates fast and sounds high, while a large drum vibrates slowly and sounds low. | Loudness depends on the size of the vibration and is measured in decibels.",["Fast vibration: high pitch","Big vibration: loud"],"sound-waves"),
 S("How your ear works","Sound waves enter your ear and make your eardrum vibrate. | Three tiny bones pass the vibration on to the inner ear. | There the vibrations are changed into signals that your brain understands as sound.",["Eardrum vibrates","Tiny bones pass it on","The brain makes sense of it"]),
],facts=["Sound moves about 340 metres per second in air, and much faster in water and steel.","An echo is a sound that bounces back from a hard surface.","Very loud sounds over a long time can damage hearing."],
quiz=[Q("What makes sound?",["Vibrations","Light","Magnets"],0,"Sound comes from vibrations."),
Q("Why is there no sound in space?",["Space is too cold","There is no air to carry the waves","Space is too bright"],1,"Sound needs a medium to travel through."),
Q("A small fast vibration gives a...",["High pitch","Low pitch","Silent sound"],0,"Faster vibrations give a higher pitch.")],tags=["sound","vibration","ear"])

L("science","forces-and-motion","11-13","Forces and Motion","Newton's three laws in everyday words, with friction, gravity and inertia.","🍎",[
 S("What is a force?","A force is a push or a pull. | Forces can start something moving, stop it, speed it up or change its direction. | We measure force in a unit called the newton.",["A push or a pull","Measured in newtons"]),
 S("Newton's first law","An object stays still, or keeps moving in a straight line at the same speed, unless a force acts on it. | This tendency is called inertia. | That is why you lean forward when a bus suddenly brakes.",["Inertia","Things keep doing what they were doing"]),
 S("Newton's second and third laws","The harder you push something, the faster it speeds up, and the heavier it is, the harder it is to push. | For every action there is an equal and opposite reaction. | When you push a wall, the wall pushes back on you.",["More force, more acceleration","Action and reaction"]),
 S("Gravity and friction","Gravity is the pull between objects, and on Earth it pulls everything toward the ground. | Friction is the force that slows things sliding over each other, and it is what lets us walk without slipping. | Without gravity and friction our everyday world would be very different.",["Gravity pulls down","Friction slows sliding"]),
],facts=["On the Moon you would weigh about one sixth of your weight on Earth, because its gravity is weaker.","In a vacuum a feather and a hammer fall together: astronauts showed this on the Moon in 1971.","Friction produces heat: rub your hands together to feel it."],
quiz=[Q("What is inertia?",["A kind of energy","The tendency to keep doing what it is doing","A type of friction"],1,"Inertia is resistance to changes in motion."),
Q("What force slows things sliding over each other?",["Gravity","Friction","Magnetism"],1,"Friction opposes sliding."),
Q("Newton's third law talks about...",["Action and reaction","Light","Heat"],0,"Every action has an equal and opposite reaction.")],tags=["newton","force","gravity"])
